const press=async(setId,from,to)=>{const s=await get(setId); const a=s.children.find(c=>c.name===from), b=s.children.find(c=>c.name===to); await a.setReactionsAsync([{trigger:{type:'ON_PRESS'},actions:[{type:'NODE',destinationId:b.id,navigation:'CHANGE_TO',transition:{type:'DISSOLVE',duration:0.1,easing:{type:'EASE_OUT'}}}]}]);};
