await press('14:73','State=Default','State=Pressed');
// navigation
const sp=await get('18:55'), gs=await get('18:76'), si=await get('18:105'), home=await get('19:119');
await sp.setReactionsAsync([{trigger:{type:'AFTER_TIMEOUT',timeout:2},actions:[nav(gs.id,dissolve)]}]);
